        services.AddScoped<IRepositoryBase<User, Guid>, RepositoryBase<User, Guid>>();
        services.AddScoped<IRepositoryBase<UserRole, Guid>, RepositoryBase<UserRole, Guid>>();

        return services;
    }
}

